"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type AuroraRimProps = {
  children: React.ReactNode;
  active?: boolean;
  className?: string;
};

/**
 * Aurora rim wrapper — iridescent orbit for working composers / panels.
 */
function AuroraRim({ children, active = true, className }: AuroraRimProps) {
  return (
    <div className={cn("relative", className)}>
      <div
        aria-hidden
        className={cn(
          "pointer-events-none absolute -inset-px overflow-hidden rounded-[inherit] transition-opacity duration-500",
          active ? "opacity-100" : "opacity-0",
        )}
        style={{ borderRadius: "inherit" }}
      >
        <div
          className={cn(
            "absolute inset-0 rounded-[1.25rem]",
            active && "animate-[joy-aura-spin_3.2s_linear_infinite]",
          )}
          style={{
            background:
              "conic-gradient(from 20deg, transparent 0%, color-mix(in oklch, var(--color-primary) 80%, white) 12%, transparent 24%, color-mix(in oklch, var(--color-chart-4) 75%, white) 40%, transparent 52%, color-mix(in oklch, var(--color-chart-2) 70%, white) 68%, transparent 80%, color-mix(in oklch, var(--color-primary) 80%, white) 92%, transparent 100%)",
            padding: "1.5px",
            WebkitMask:
              "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
            WebkitMaskComposite: "xor",
            maskComposite: "exclude",
          }}
        />
      </div>
      {active ? (
        <div
          aria-hidden
          className="pointer-events-none absolute inset-3 rounded-[1rem] opacity-35 blur-2xl"
          style={{
            background:
              "radial-gradient(ellipse at 25% 35%, color-mix(in oklch, var(--color-primary) 30%, transparent), transparent 55%), radial-gradient(ellipse at 75% 65%, color-mix(in oklch, var(--color-chart-4) 24%, transparent), transparent 50%)",
          }}
        />
      ) : null}
      <div className="relative z-[1]">{children}</div>
    </div>
  );
}

export { AuroraRim };
